def feature(s):
    props = s.get('element_properties') or {}
    data = []
    total = 0.0
    inverse = 0.0
    numerator = 0.0
    for e, x in (s.get('composition') or {}).items():
        p = props.get(e) or {}
        ie = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if x is not None and math.isfinite(x) and x > 0 and ie is not None and ea is not None and math.isfinite(ie) and math.isfinite(ea) and ie - ea > 0.000001:
            hardness = ie - ea
            chi = 0.5 * (ie + ea)
            data = data + [(x, chi, hardness)]
            total += x
            inverse += x / hardness
            numerator += x * chi / hardness
    if total <= 0 or inverse <= 0:
        return 0.0
    equilibrium = numerator / inverse
    return float(sum(x * (chi - equilibrium) ** 2 / (2.0 * hardness) for x, chi, hardness in data) / total)

